CREATE OR REPLACE FUNCTION public.append_audit_event_chained(p_id uuid, p_organization_id uuid, p_actor_user_id uuid, p_action text, p_entity_type text, p_entity_id text, p_metadata jsonb, p_created_at timestamp with time zone, p_previous_hash text, p_event_hash text, p_hash_signature text DEFAULT NULL::text, p_hash_algorithm text DEFAULT 'sha256'::text)
 RETURNS audit_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_previous_hash text;
  v_inserted public.audit_events;
begin
  if p_id is null then
    raise exception 'id is required' using errcode = '23502';
  end if;
  if p_organization_id is null then
    raise exception 'organization_id is required' using errcode = '23502';
  end if;
  if p_action is null or length(trim(p_action)) = 0 then
    raise exception 'action is required' using errcode = '23502';
  end if;
  if p_entity_type is null or length(trim(p_entity_type)) = 0 then
    raise exception 'entity_type is required' using errcode = '23502';
  end if;
  if p_created_at is null then
    raise exception 'created_at is required' using errcode = '23502';
  end if;
  if p_event_hash is null or length(trim(p_event_hash)) = 0 then
    raise exception 'event_hash is required' using errcode = '23502';
  end if;
  if p_hash_algorithm is null or p_hash_algorithm <> 'sha256' then
    raise exception 'hash_algorithm must be sha256' using errcode = '22023';
  end if;

  if not pg_try_advisory_xact_lock(hashtext(p_organization_id::text)) then
    raise exception 'audit chain write conflict: lock unavailable' using errcode = '55P03';
  end if;

  select ae.event_hash
    into v_previous_hash
  from public.audit_events ae
  where ae.organization_id = p_organization_id
    and ae.event_hash is not null
  order by ae.created_at desc, ae.id desc
  limit 1;

  if coalesce(v_previous_hash, '') <> coalesce(p_previous_hash, '') then
    raise exception 'audit chain write conflict: stale head' using errcode = 'P0001';
  end if;

  insert into public.audit_events (
    id, organization_id, actor_user_id, action, entity_type, entity_id,
    metadata, created_at, previous_hash, event_hash, hash_algorithm, hash_signature
  ) values (
    p_id, p_organization_id, p_actor_user_id, p_action, p_entity_type, p_entity_id,
    coalesce(p_metadata, '{}'::jsonb), p_created_at, v_previous_hash, p_event_hash,
    p_hash_algorithm, p_hash_signature
  )
  returning * into v_inserted;

  return v_inserted;
end;
$function$

CREATE OR REPLACE FUNCTION public.release_organization_seat_atomic(p_organization_id uuid, p_member_id uuid, p_actor_user_id uuid, p_idempotency_key text, p_source text DEFAULT 'admin'::text)
 RETURNS TABLE(outcome text, membership_id uuid, released_seat_type text, active_members integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_membership public.organization_members%rowtype;
  v_operation_id uuid;
  v_source text := lower(trim(coalesce(p_source,'')));
  v_active_members integer := 0;
  v_full_users integer := 0;
  v_participants integer := 0;
  v_viewers integer := 0;
  v_active_admins integer := 0;
begin
  if p_organization_id is null or p_member_id is null or p_actor_user_id is null
     or length(trim(coalesce(p_idempotency_key,''))) not between 8 and 200 then
    return query select 'invalid_input'::text,null::uuid,null::text,0; return;
  end if;
  if v_source not in ('invitation','csv','scim','sso','api','platform','admin','reactivation') then
    return query select 'invalid_source'::text,null::uuid,null::text,0; return;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_organization_id::text || ':' || p_idempotency_key,0));
  insert into public.enterprise_seat_operations (organization_id,idempotency_key,operation,source,actor_user_id)
  values (p_organization_id,p_idempotency_key,'release',v_source,p_actor_user_id)
  on conflict (organization_id,idempotency_key) do nothing returning id into v_operation_id;
  if v_operation_id is null then return query select 'duplicate'::text,null::uuid,null::text,0; return; end if;

  insert into public.organization_usage (organization_id) values (p_organization_id)
  on conflict (organization_id) do nothing;
  perform 1 from public.organization_usage as usage where usage.organization_id=p_organization_id for update;

  select member.* into v_membership from public.organization_members as member
  where member.organization_id=p_organization_id and member.id=p_member_id for update;
  if not found then
    update public.enterprise_seat_operations set outcome='not_found',completed_at=now() where id=v_operation_id;
    return query select 'not_found'::text,p_member_id,null::text,0; return;
  end if;
  if v_membership.status<>'active' then
    select count(*)::integer into v_active_members from public.organization_members
    where organization_id=p_organization_id and status='active';
    update public.enterprise_seat_operations set outcome='already_released',membership_id=v_membership.id,completed_at=now() where id=v_operation_id;
    return query select 'already_released'::text,v_membership.id,v_membership.seat_type,v_active_members; return;
  end if;

  update public.organization_members set status=case when v_source='scim' then 'deprovisioned' else 'suspended' end,updated_at=now()
  where id=v_membership.id and organization_id=p_organization_id;

  select count(*) filter (where member.status='active')::integer,
    count(*) filter (where member.status='active' and member.seat_type='full')::integer,
    count(*) filter (where member.status='active' and member.seat_type='participant')::integer,
    count(*) filter (where member.status='active' and member.seat_type='viewer')::integer,
    count(*) filter (where member.status='active' and lower(coalesce(member.role,'')) in ('owner','admin'))::integer
  into v_active_members,v_full_users,v_participants,v_viewers,v_active_admins
  from public.organization_members as member where member.organization_id=p_organization_id;

  update public.organization_usage set active_members=v_active_members,full_users=v_full_users,
    participants=v_participants,viewers=v_viewers,active_admins=v_active_admins,last_reconciled_at=now(),updated_at=now()
  where organization_id=p_organization_id;

  insert into public.audit_logs (organization_id,actor_id,action,entity_type,entity_id,metadata)
  values (p_organization_id,p_actor_user_id,'enterprise.seat_released','organization_member',v_membership.id::text,
    jsonb_build_object('source',v_source,'seat_type',v_membership.seat_type));

  update public.enterprise_seat_operations set outcome='released',membership_id=v_membership.id,completed_at=now(),
    metadata=jsonb_build_object('active_members',v_active_members) where id=v_operation_id;
  return query select 'released'::text,v_membership.id,v_membership.seat_type,v_active_members;
end;
$function$

CREATE OR REPLACE FUNCTION public.change_organization_member_role_atomic(p_organization_id uuid, p_member_id uuid, p_expected_role text, p_next_role text)
 RETURNS TABLE(outcome text, affected_member_id uuid, affected_user_id uuid, previous_role text, applied_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_member public.organization_members%rowtype;
  v_contract public.enterprise_contracts%rowtype;
  v_entitlement public.organization_entitlements%rowtype;
  v_next_role text := lower(trim(coalesce(p_next_role, '')));
  v_expected_role text := lower(trim(coalesce(p_expected_role, '')));
  v_owner_count integer;
  v_active_admins integer;
  v_pending_admins integer;
  v_admin_limit integer;
begin
  if p_organization_id is null or p_member_id is null then
    return query select 'invalid_input'::text, null::uuid, null::uuid, null::text, null::text;
    return;
  end if;

  if v_next_role not in ('owner', 'admin', 'editor', 'member', 'viewer') then
    return query select 'invalid_role'::text, p_member_id, null::uuid, null::text, null::text;
    return;
  end if;

  insert into public.organization_usage (organization_id)
  values (p_organization_id)
  on conflict (organization_id) do nothing;

  perform 1
  from public.organization_usage as usage
  where usage.organization_id = p_organization_id
  for update;

  select member.* into v_member
  from public.organization_members as member
  where member.id = p_member_id
    and member.organization_id = p_organization_id
  for update;

  if not found then
    return query select 'not_found'::text, p_member_id, null::uuid, null::text, null::text;
    return;
  end if;

  if lower(coalesce(v_member.role, '')) is distinct from v_expected_role then
    return query select 'state_changed'::text, p_member_id, v_member.user_id, v_member.role, null::text;
    return;
  end if;

  if lower(coalesce(v_member.role, 'viewer')) = v_next_role then
    return query select 'unchanged'::text, p_member_id, v_member.user_id, v_member.role, v_member.role;
    return;
  end if;

  if lower(coalesce(v_member.role, '')) = 'owner' and v_next_role <> 'owner' then
    select count(*)::integer into v_owner_count
    from public.organization_members as member
    where member.organization_id = p_organization_id
      and member.status = 'active'
      and lower(coalesce(member.role, '')) = 'owner';

    if v_owner_count <= 1 then
      return query select 'last_owner'::text, p_member_id, v_member.user_id, v_member.role, null::text;
      return;
    end if;
  end if;

  if v_next_role in ('owner', 'admin')
    and lower(coalesce(v_member.role, '')) not in ('owner', 'admin') then
    select contract.* into v_contract
    from public.enterprise_contracts as contract
    where contract.organization_id = p_organization_id
      and contract.status in (
        'draft', 'pending_activation', 'active', 'past_due', 'grace_period',
        'read_only', 'suspended'
      )
    order by contract.version desc, contract.updated_at desc
    limit 1
    for update;

    if not found or v_contract.status <> 'active' then
      return query select 'contract_not_active'::text, p_member_id, v_member.user_id, v_member.role, null::text;
      return;
    end if;

    select entitlement.* into v_entitlement
    from public.organization_entitlements as entitlement
    where entitlement.organization_id = p_organization_id
      and entitlement.contract_id = v_contract.id
    for update;

    if not found then
      return query select 'entitlements_missing'::text, p_member_id, v_member.user_id, v_member.role, null::text;
      return;
    end if;

    select count(*)::integer into v_active_admins
    from public.organization_members as member
    where member.organization_id = p_organization_id
      and member.status = 'active'
      and lower(coalesce(member.role, '')) in ('owner', 'admin');

    select count(*)::integer into v_pending_admins
    from public.invitations as invitation
    where invitation.organization_id = p_organization_id
      and invitation.accepted_at is null
      and invitation.revoked_at is null
      and invitation.expires_at > now()
      and lower(coalesce(invitation.role, '')) in ('owner', 'admin');

    v_admin_limit := least(v_contract.admin_limit, v_entitlement.admin_limit);

    if v_active_admins + v_pending_admins >= v_admin_limit then
      return query select 'admin_limit_reached'::text, p_member_id, v_member.user_id, v_member.role, null::text;
      return;
    end if;
  end if;

  update public.organization_members as member
  set role = v_next_role,
      updated_at = now()
  where member.id = p_member_id
    and member.organization_id = p_organization_id
    and lower(coalesce(member.role, '')) = v_expected_role;

  if not found then
    return query select 'state_changed'::text, p_member_id, v_member.user_id, v_member.role, null::text;
    return;
  end if;

  return query select 'changed'::text, p_member_id, v_member.user_id, v_member.role, v_next_role;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_organization_member_atomic(p_organization_id uuid, p_member_id uuid, p_expected_user_id uuid, p_expected_role text)
 RETURNS TABLE(outcome text, affected_member_id uuid, affected_user_id uuid, previous_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_user_id uuid;
  v_previous_role text;
  v_owner_count integer;
begin
  if p_organization_id is null or p_member_id is null or p_expected_user_id is null then
    return query select
      'invalid_input'::text,
      null::uuid,
      null::uuid,
      null::text;
    return;
  end if;

  -- Lock every membership row for this organization in a stable order. This
  -- serializes owner-count decisions, role transitions and removals for the tenant.
  perform 1
  from public.organization_members as om
  where om.organization_id = p_organization_id
  order by om.id
  for update;

  select om.user_id, om.role
    into v_user_id, v_previous_role
  from public.organization_members as om
  where om.id = p_member_id
    and om.organization_id = p_organization_id;

  if not found then
    return query select
      'not_found'::text,
      p_member_id,
      null::uuid,
      null::text;
    return;
  end if;

  if v_user_id is distinct from p_expected_user_id
    or v_previous_role is distinct from p_expected_role then
    return query select
      'state_changed'::text,
      p_member_id,
      v_user_id,
      v_previous_role;
    return;
  end if;

  if lower(coalesce(v_previous_role, '')) = 'owner' then
    select count(*)::integer
      into v_owner_count
    from public.organization_members as om
    where om.organization_id = p_organization_id
      and lower(coalesce(om.role, '')) = 'owner';

    if v_owner_count <= 1 then
      return query select
        'last_owner'::text,
        p_member_id,
        v_user_id,
        v_previous_role;
      return;
    end if;
  end if;

  delete from public.organization_members as om
  where om.id = p_member_id
    and om.organization_id = p_organization_id
    and om.user_id = p_expected_user_id
    and om.role is not distinct from p_expected_role;

  if not found then
    return query select
      'state_changed'::text,
      p_member_id,
      v_user_id,
      v_previous_role;
    return;
  end if;

  return query select
    'removed'::text,
    p_member_id,
    v_user_id,
    v_previous_role;
end;
$function$
